insert into robots (slug, name, brand, category_id, score, summary, pros, cons, specs, status, verdict, best_for, not_for, comparison_tags, calculator_tags) values
('unitree-g1','Unitree G1','Unitree',(select id from categories where slug='humanoids'),7.5,'הומנואיד סיני שכבר נמכר בפועל למפתחים ומוסדות, במחיר גבוה משמעותית ממוצרי צריכה רגילים.',ARRAY['נמכר בפועל כיום, לא רק הכרזה','גמישות תנועה גבוהה ל-23 מפרקים ומעלה'],ARRAY['מיועד למפתחים ומוסדות, לא לצרכן הביתי הרגיל','מחיר גבוה מאוד'],'{"סטטוס":"נמכר בפועל למפתחים ומוסדות","מפרקים":"23 ומעלה"}','published','הדגם ההומנואידי הכי נגיש היום לרכישה בפועל, אך עדיין לא מוצר צריכה ביתי.',ARRAY['מוסדות מחקר ומפתחי רובוטיקה'],ARRAY['שימוש ביתי יומיומי'],ARRAY['developer'],ARRAY['humanoids']),
('unitree-h1','Unitree H1','Unitree',(select id from categories where slug='humanoids'),7.8,'הומנואיד גדול יותר של Unitree בגובה אדם, מיועד למחקר ופיתוח מתקדם.',ARRAY['גובה וכוח קרובים לאדם בוגר','מהיר יחסית לקטגוריה'],ARRAY['מחיר גבוה מאוד, לא מוצר צריכה'],'{"סטטוס":"נמכר למוסדות ומפתחים","גובה":"בגובה אדם בוגר בקירוב"}','published','אחד ההומנואידים המהירים והמתקדמים שנמכרים בפועל כיום, אך למגזר המחקר בלבד.',ARRAY['מוסדות מחקר מתקדמים'],ARRAY['צרכן ביתי'],ARRAY['developer'],ARRAY['humanoids']),
('1x-neo-beta','1X NEO Beta','1X Technologies',(select id from categories where slug='humanoids'),null,'הומנואיד המיועד לשימוש ביתי, כרגע בשלב רשימת המתנה/בטא מוגבלת ולא במכירה כללית.',ARRAY['תוכנן מההתחלה לשימוש ביתי, לא תעשייתי'],ARRAY['לא זמין לרכישה כללית — רשימת המתנה בלבד כרגע'],'{"סטטוס":"רשימת המתנה / בטא מוגבלת"}','published','המועמד המעניין ביותר להומנואיד ביתי אמיתי, אך עדיין לא ניתן לרכישה בישראל או בעולם.',ARRAY['מי שרוצה להירשם מוקדם לרשימת המתנה'],ARRAY['מי שמחפש רכישה מיידית'],ARRAY['waitlist'],ARRAY['humanoids']),
('ubtech-walker-s','UBTECH Walker S','UBTECH',(select id from categories where slug='humanoids'),7.2,'הומנואיד סיני שנפרס בעיקר בקווי ייצור ומחסנים, לא מוצר צריכה.',ARRAY['כבר בפריסה בפועל בסביבות תעשייתיות','חברה עם ניסיון ארוך ברובוטיקה צרכנית (Alpha, Cruzr)'],ARRAY['מיועד לתעשייה, לא לבית'],'{"סטטוס":"בפריסה תעשייתית"}','published','דוגמה לכך שהומנואידים כבר עובדים בפועל — אך בתעשייה, לא בבית.',ARRAY['יישומים תעשייתיים ולוגיסטיים'],ARRAY['שימוש ביתי'],ARRAY['industrial'],ARRAY['humanoids']),
('tesla-optimus','Tesla Optimus','Tesla',(select id from categories where slug='humanoids'),null,'ההומנואיד המוכר ביותר בתקשורת, אך נכון להיום עדיין לא מוצר הנמכר לצרכנים.',ARRAY['פיתוח מהיר ותקציב עצום מאחוריו'],ARRAY['אינו נמכר כלל לצרכנים כרגע — אין תאריך יעד רשמי'],'{"סטטוס":"טרם נמכר לצרכנים"}','published','אנחנו עוקבים אחריו, אבל נכון להיום אין מה לקנות — נעדכן ברגע שיהיה.',ARRAY['מי שרוצה להישאר מעודכן על הקטגוריה'],ARRAY['מי שרוצה לקנות הומנואיד היום'],ARRAY['upcoming'],ARRAY['humanoids'])
