('tombot-jennie','Tombot Jennie','Tombot',(select id from categories where slug='companions'),7.9,'גור כלב רובוטי מטיפולי, מיועד בעיקר לקשישים ולאנשים עם דמנציה, עם תגובות מגע ריאליסטיות.',ARRAY['מיועד ספציפית לטיפול ותמיכה רגשית','תגובות מגע וקול ריאליסטיות במיוחד'],ARRAY['לא נועד למשחק פעיל כמו רובוט ילדים'],'{"ייעוד":"טיפולי, לקשישים ואנשים עם דמנציה"}','published','הכי מתאים לצרכי תמיכה רגשית וטיפולית, פחות למשחק פעיל.',ARRAY['קשישים ואנשים עם דמנציה'],ARRAY['ילדים שרוצים משחק פעיל'],ARRAY['therapeutic'],ARRAY['companions']),
('loona-petbot','Loona','KEYi Tech',(select id from categories where slug='companions'),7.6,'רובוט חמוד בגודל קטן עם עיניים דיגיטליות אקספרסיביות ואפליקציית אינטראקציה.',ARRAY['עיצוב חמוד ואקספרסיבי במיוחד','מחיר נגיש יחסית לקטגוריה'],ARRAY['פחות "חכם" מבחינת יכולות AI מתקדמות'],'{"עיצוב":"עיניים דיגיטליות אקספרסיביות"}','published','אופציה נגישה וחמודה למי שרוצה רובוט-חיה בלי מחיר פרימיום.',ARRAY['משפחות עם ילדים שרוצות רובוט חמוד'],ARRAY['מי שמחפש AI מתקדם במיוחד'],ARRAY['value','cute'],ARRAY['companions']),
('moflin','Moflin','Casio (Vanguard Industries)',(select id from categories where slug='companions'),7.4,'יצור רובוטי פרוותי קטן שמפתח "רגשות" מבוססי אינטראקציה, ללא צורה של חיה מוכרת.',ARRAY['פרווה רכה ומרקם נעים למגע','מפתח דפוסי "מצב רוח" ייחודיים לפי אינטראקציה'],ARRAY['ללא תנועה עצמאית משמעותית'],'{"עיצוב":"יצור פרוותי, לא צורת חיה מוכרת"}','published','חוויית מגע ורגש ייחודית, אבל בלי תנועה עצמאית כמו רובוטים אחרים בקטגוריה.',ARRAY['מי שמחפש חוויית מגע רגועה ומרגיעה'],ARRAY['מי שרוצה רובוט שזז וחוקר בעצמו'],ARRAY['sensory'],ARRAY['companions']),
('petoi-bittle','Petoi Bittle','Petoi',(select id from categories where slug='companions'),7.7,'כלב רובוטי בבנייה עצמית (קיט) בקוד פתוח, מיועד לחובבי טכנולוגיה ולימוד רובוטיקה.',ARRAY['קוד פתוח וניתן לתכנות עצמאי','חוויית בנייה חינוכית'],ARRAY['דורש הרכבה וידע טכני בסיסי'],'{"סוג":"קיט הרכבה, קוד פתוח"}','published','הבחירה למי שרוצה ללמוד רובוטיקה, לא רק לקנות רובוט מוגמר.',ARRAY['נוער ומבוגרים שאוהבים DIY וטכנולוגיה'],ARRAY['מי שרוצה מוצר מוגמר מהקופסה'],ARRAY['diy','open-source'],ARRAY['companions']),
('petoi-nybble','Petoi Nybble','Petoi',(select id from categories where slug='companions'),7.5,'חתול רובוטי בבנייה עצמית מאותה חברה כמו Bittle, קוד פתוח וניתן לתכנות.',ARRAY['קוד פתוח','קהילת מפתחים פעילה'],ARRAY['דורש הרכבה וידע טכני'],'{"סוג":"קיט הרכבה, קוד פתוח"}','published','גרסת החתול לאותה חוויית DIY חינוכית כמו Bittle.',ARRAY['חובבי DIY ורובוטיקה'],ARRAY['מי שרוצה מוצר מוגמר'],ARRAY['diy','open-source'],ARRAY['companions']),
('anki-vector','Anki Vector','Anki (Digital Dream Labs)',(select id from categories where slug='companions'),7.0,'רובוט שולחני אקספרסיבי עם אישיות, המשיך לפעול תחת בעלים חדשים אחרי סגירת החברה המקורית.',ARRAY['אישיות ותגובות מפותחות במיוחד לגודלו','מזהה פנים וקול'],ARRAY['החברה המקורית נסגרה — תמיכה ארוכת טווח פחות ודאית'],'{"היסטוריה":"פותח ע״י Anki, נרכש ע״י Digital Dream Labs"}','published','חוויה מקורית ומפותחת, אבל כדאי לבדוק זמינות תמיכה עדכנית לפני רכישה.',ARRAY['אספני רובוטיקה וטכנולוגיה'],ARRAY['מי שרוצה תמיכת יצרן יציבה לטווח ארוך'],ARRAY['legacy'],ARRAY['companions']),
('circuitmess-nova','CircuitMess Nova','CircuitMess',(select id from categories where slug='companions'),7.1,'רובוט חינוכי בבנייה עצמית עם מסך ופרצוף דיגיטלי, מיועד ללימוד קוד ואלקטרוניקה.',ARRAY['ערכת בנייה חינוכית מלאה','מלמד תכנות ואלקטרוניקה בפועל'],ARRAY['מיועד ללמידה, פחות ל"חברות" יומיומית'],'{"סוג":"קיט חינוכי בבנייה עצמית"}','published','הכי טוב כמתנה חינוכית שמלמדת קוד, פחות כרובוט-חיה יומיומי.',ARRAY['ילדים ונוער שרוצים ללמוד תכנות'],ARRAY['מי שמחפש חוויית ליווי רגשי'],ARRAY['educational','diy'],ARRAY['companions']),
