('ropet','Ropet','Ropet Robotics',(select id from categories where slug='companions'),7.2,'רובוט-חיה קטן ומחמד המגיב לליטוף ולקול, ממוקד קהל מבוגרים וקשישים לחברה יומיומית.',ARRAY['תגובות ליטוף וקול פשוטות ומרגיעות','גודל קטן ונוח לאחזקה'],ARRAY['פחות יכולות "חכמות" מתקדמות'],'{"ייעוד":"חברה יומיומית, בעיקר לקשישים"}','published','חברה פשוטה ומרגיעה, פחות מוצר טכנולוגי מתקדם.',ARRAY['קשישים המחפשים חברה פשוטה'],ARRAY['מי שמחפש יכולות AI מתקדמות'],ARRAY['simple'],ARRAY['companions'])
