('lego-spike-prime','LEGO Education SPIKE Prime','LEGO',(select id from categories where slug='kids-robots'),8.8,'ערכת רובוטיקה חינוכית מבוססת LEGO, עם חיישנים ותכנות ויזואלי מבוסס Scratch.',ARRAY['תכנות ויזואלי ידידותי מבוסס Scratch','חלקי LEGO תואמים לערכות קיימות'],ARRAY['מחיר גבוה יחסית כערכה חינוכית'],'{"תכנות":"ויזואלי, מבוסס Scratch","גיל מומלץ":"מגיל 10 ומעלה"}','published','אחת מערכות הרובוטיקה החינוכיות המובילות בעולם, גם בבתי ספר בישראל.',ARRAY['ילדים שרוצים ללמוד תכנות ורובוטיקה ברצינות'],ARRAY['תקציב מוגבל למתנה חד-פעמית'],ARRAY['educational'],ARRAY['kids-robots']),
('lego-mindstorms-robot-inventor','LEGO Mindstorms Robot Inventor','LEGO',(select id from categories where slug='kids-robots'),8.5,'ערכת הרובוטיקה המתקדמת של LEGO להרכבת חמישה דגמי רובוט שונים עם תכנות מלא.',ARRAY['חמישה דגמי רובוט מוכנים בערכה אחת','תכנות מתקדם יותר עבור ילדים גדולים יותר'],ARRAY['הפסקת ייצור רשמית — זמינות תלויה במלאי קיים'],'{"תכנות":"ויזואלי ומתקדם","דגמים":"5 רובוטים שונים בערכה"}','published','עדיין אחת הערכות המתקדמות ביותר שקיימות, כדאי לבדוק זמינות מלאי.',ARRAY['ילדים גדולים יותר שרוצים אתגר מתקדם'],ARRAY['ילדים צעירים מדי לתכנות מורכב'],ARRAY['educational'],ARRAY['kids-robots']),
('sphero-bolt','Sphero BOLT','Sphero',(select id from categories where slug='kids-robots'),8.2,'כדור רובוטי מתגלגל עם מסך LED מלא ותכנות ויזואלי, פופולרי מאוד בבתי ספר.',ARRAY['עמיד ואיכותי, שורד נפילות היטב','מסך LED מלא לאנימציות ותצוגות'],ARRAY['פחות "בנייה" פיזית — הצורה קבועה'],'{"תכנות":"ויזואלי (Sphero Edu)","עיצוב":"כדור עמיד עם LED"}','published','אחד המוצרים החינוכיים הפופולריים ביותר בעולם, מתאים גם למשחק וגם ללימוד.',ARRAY['ילדים בגיל בית ספר יסודי'],ARRAY['ילדים שרוצים לבנות ולהרכיב פיזית'],ARRAY['educational'],ARRAY['kids-robots']),
('sphero-indi','Sphero Indi','Sphero',(select id from categories where slug='kids-robots'),7.9,'רובוט מתגלגל על מסלולי צבע, מיועד לילדים צעירים ללמוד יסודות תכנות בלי מסך.',ARRAY['תכנות ללא מסך, מבוסס כרטיסי צבע פיזיים','מתאים לגילאי גן וכיתות נמוכות'],ARRAY['פחות מתקדם לילדים גדולים יותר'],'{"תכנות":"כרטיסי צבע פיזיים, ללא מסך","גיל מומלץ":"מגיל 4"}','published','המתאים ביותר לגיל הצעיר ביותר בקטגוריה, בלי צורך במסך כלל.',ARRAY['ילדי גן וכיתות א-ב'],ARRAY['ילדים גדולים שרוצים תכנות מתקדם'],ARRAY['educational','young-kids'],ARRAY['kids-robots']),
('wonder-workshop-dash','Wonder Workshop Dash','Wonder Workshop',(select id from categories where slug='kids-robots'),8.0,'רובוט חינוכי אקספרסיבי עם עיניים ותנועה, נלמד באפליקציות מדורגות לפי גיל.',ARRAY['אפליקציות מדורגות לפי רמת גיל','אישיות ותגובות חמודות שמושכות ילדים צעירים'],ARRAY['מחיר גבוה יחסית לרובוט אחד'],'{"תכנות":"אפליקציות מדורגות (Blockly)","גיל מומלץ":"מגיל 6"}','published','שילוב טוב בין אישיות מושכת ללימוד תכנות מדורג.',ARRAY['ילדים בגילאי בית ספר יסודי'],ARRAY['תקציב מוגבל'],ARRAY['educational'],ARRAY['kids-robots']),
